// Transfer is a proposed change of holder, and the record of who agreed to it.
//
// It is kept after completion, not deleted. The history of who signed what and
// when is the receipt that a dispossessed owner currently does not have, and
// deleting it to save space would remove the only thing that makes the theft
// arguable afterwards.
type Transfer struct {
	Id       uint64 `protobuf:"varint,1,opt,name=id,proto3" json:"id,omitempty"`
	ParcelId uint64 `protobuf:"varint,2,opt,name=parcel_id,json=parcelId,proto3" json:"parcel_id,omitempty"`
	From     string `protobuf:"bytes,3,opt,name=from,proto3" json:"from,omitempty"`
	To       string `protobuf:"bytes,4,opt,name=to,proto3" json:"to,omitempty"`
	// Declared consideration. Recorded for the audit trail; the chain does not
	// move it. Land paid for off-chain is the common case and pretending
	// otherwise would make the record false.
	Price string `protobuf:"bytes,5,opt,name=price,proto3" json:"price,omitempty"`
	// Set when the jurisdiction's own office validates.
	Validated   bool   `protobuf:"varint,6,opt,name=validated,proto3" json:"validated,omitempty"`
	ValidatedBy string `protobuf:"bytes,7,opt,name=validated_by,json=validatedBy,proto3" json:"validated_by,omitempty"`
	// Independent registrars who have attested, one entry each. The keeper
	// refuses an attestation from the proposing authority: an attestor from the
	// same office is not independent, and allowing it collapses the whole
	// mechanism back to a single bribe.
	Attestors []string `protobuf:"bytes,8,rep,name=attestors,proto3" json:"attestors,omitempty"`
	// When quorum was reached. The challenge window runs from here, not from
	// proposal, so the public clock starts only once the transfer is real.
	QuorumAt int64 `protobuf:"varint,9,opt,name=quorum_at,json=quorumAt,proto3" json:"quorum_at,omitempty"`
	// First objection, if any. One is enough to stop everything.
	ObjectedBy      string `protobuf:"bytes,10,opt,name=objected_by,json=objectedBy,proto3" json:"objected_by,omitempty"`
	ObjectionReason string `protobuf:"bytes,11,opt,name=objection_reason,json=objectionReason,proto3" json:"objection_reason,omitempty"`
	ProposedAt      int64  `protobuf:"varint,12,opt,name=proposed_at,json=proposedAt,proto3" json:"proposed_at,omitempty"`
	CompletedAt     int64  `protobuf:"varint,13,opt,name=completed_at,json=completedAt,proto3" json:"completed_at,omitempty"`
}

